// HasUsedByUser applies the HasEdge predicate on the "used_by_user" edge.
func HasUsedByUser() predicate.RedeemCode {
	return predicate.RedeemCode(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UsedByUserTable, UsedByUserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUsedByUserWith applies the HasEdge predicate on the "used_by_user" edge with a given conditions (other predicates).
func HasUsedByUserWith(preds ...predicate.User) predicate.RedeemCode {
	return predicate.RedeemCode(func(s *sql.Selector) {
		step := newUsedByUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCreator applies the HasEdge predicate on the "creator" edge.
